INSERT OR IGNORE INTO monster_actions (monster_id, action_type, action_icon, name, description, check_formula, accuracy_bonus, damage_formula, damage_type, cost, target, duration, is_offensive) VALUES ((SELECT id FROM monsters WHERE name = 'Dracoardil'), 'basic_attack', 'melee', 'Devorador de Dragões', 'Causa (RA + 10) de dano físico. Se um alvo atingido pelo ataque estiver fraco, ele é engolido pelo dracoardil. Uma criatura engolida sofre dano físico fraco (20) no início de cada turno do dracoardil e não pode fazer ações, exceto por Objetivo com a intenção de se libertar. Fazer um alvo engolido ser liberado exige um relógio de quatro seções. Um dracoardil soldado só pode ter uma criatura de tamanho humano engolida por vez; já um dracoardil campeão, substituindo três ou mais soldados, pode ter até duas por vez. Se o dracoardil tiver todas as bocas ocupadas e engolir alguém, ele deve primeiro liberar uma das criaturas engolidas anteriormente.', 'VIG + VIG', 5, NULL, 'physical', NULL, NULL, NULL, 1);
